@lru_cache
def genre_catalog():
    labels=dict(pair.split('=',1) for pair in LABELS.split('|'))
    root=ET.fromstring(files('storygen.publication').joinpath('resources/fb2/FictionBookGenres.xsd').read_bytes())
    codes=[e.attrib['value'] for e in root.findall('.//{http://www.w3.org/2001/XMLSchema}enumeration')]
    if set(codes)!=set(labels):
        raise ValueError('Жанровий каталог і українські підписи не узгоджені')
    return tuple((code,labels[code]) for code in codes)
